// TODO(awly): combine Expression and Matcher. It should be possible to write:
// `{{regexp.match(email.local(external.trait_name))}}`
package parse

import (
	"go/ast"
	"go/parser"
	"go/token"
	"net/mail"
	"regexp"
	"strconv"
