			title: "unknown namespace",
			in:    `{{surprise.match(".*")}}`,
			err:   trace.BadParameter(""),
		},
		{
			title: "unsupported namespace",
			in:    `{{email.local(external.email)}}`,
			err:   trace.BadParameter(""),
		},
		{
			title: "unsupported variable syntax",
			in:    `{{external.email}}`,
			err:   trace.BadParameter(""),
		},
		{
			title: "string literal",
			in:    `foo`,
			out:   &regexpMatcher{re: regexp.MustCompile(`^foo$`)},
		},
		{
			title: "wildcard",
			in:    `foo*`,
			out:   &regexpMatcher{re: regexp.MustCompile(`^foo(.*)$`)},
		},
