type regexpReplaceTransformer struct {
	re          *regexp.Regexp
	replacement string
}

func (r regexpReplaceTransformer) transform(s string) (string, error) {
	if !r.re.MatchString(s) {
		return "", nil
	}
	return r.re.ReplaceAllString(s, r.replacement), nil
}
func (p *Expression) Namespace() string { return p.namespace }
func (p *Expression) Name() string      { return p.variable }

func (p *Expression) Interpolate(traits map[string][]string) ([]string, error) {
	return p.InterpolateWithValidation(traits, nil)
}
func (p *Expression) InterpolateWithValidation(traits map[string][]string, validate func(namespace, name string) error) ([]string, error) {
	stored, parsed := expressionAST.Load(p)
	if !parsed { // compatibility for direct struct literals in existing callers/tests
		if p.namespace == LiteralNamespace {
			return []string{p.variable}, nil
		}
		vals, ok := traits[p.variable]
		if !ok {
			return nil, trace.NotFound("variable %s.%s is not found", p.namespace, p.variable)
		}
		var out []string
		for _, val := range vals {
			if p.transform != nil {
				var err error
				val, err = p.transform.transform(val)
				if err != nil {
					return nil, err
				}
			}
			if val != "" {
				out = append(out, p.prefix+val+p.suffix)
			}
		}
		return out, nil
	}
	data := stored.(expressionData)
	if p.namespace == LiteralNamespace {
		return []string{p.variable}, nil
	}
	ctx := EvaluateContext{VarValue: func(v VarExpr) ([]string, error) {
		if validate != nil {
			if err := validate(v.Namespace, v.Name); err != nil {
				return nil, err
			}
		}
		values, ok := traits[v.Name]
		if !ok {
			return nil, trace.NotFound("variable %s is not found in traits", v.String())
		}
		return values, nil
	}}
	v, err := data.expr.Evaluate(ctx)
	if err != nil {
		return nil, err
	}
	values, ok := v.([]string)
	if !ok {
		return nil, trace.BadParameter("expression %q did not produce strings", data.raw)
	}
	if len(values) == 0 {
		return nil, trace.NotFound("interpolation produced no values")
	}
	out := make([]string, 0, len(values))
	for _, s := range values {
		if s != "" {
			out = append(out, p.prefix+s+p.suffix)
		}
	}
	if len(out) == 0 {
		return nil, trace.NotFound("interpolation produced no values")
	}
	return out, nil
}

func NewExpression(input string) (*Expression, error) {
	value := strings.TrimFunc(input, unicode.IsSpace)
	op, cl := strings.Index(value, "{{"), strings.Index(value, "}}")
	if op < 0 && cl < 0 {
		p := &Expression{namespace: LiteralNamespace, variable: value}
		expressionAST.Store(p, expressionData{StringLitExpr{Value: value}, input})
		return p, nil
	}
	if op < 0 || cl < op || strings.Contains(value[op+2:], "{{") || strings.Contains(value[:cl], "}}") || strings.Index(value[cl+2:], "{{") >= 0 || strings.Contains(value[cl+2:], "}}") {
		return nil, trace.BadParameter("malformed template usage in %q", input)
	}
	prefix, body, suffix := value[:op], strings.TrimSpace(value[op+2:cl]), value[cl+2:]
	ast, err := parse(body)
	if err != nil {
		return nil, trace.BadParameter("invalid expression in %q: %v", input, err)
	}
	if ast.Kind() != reflect.Slice {
		return nil, trace.BadParameter("expression %q must evaluate to a string", input)
	}
	if err := validateExpr(ast); err != nil {
		return nil, trace.BadParameter("invalid expression in %q: %v", input, err)
	}
	var root Expr = ast
	for root != nil {
		switch e := root.(type) {
		case VarExpr:
			var transformer transformer
			switch node := ast.(type) {
			case EmailLocalExpr:
				transformer = emailLocalTransformer{}
			case RegexpReplaceExpr:
				transformer = &regexpReplaceTransformer{re: node.re, replacement: node.Replacement}
			}
			p := &Expression{namespace: e.Namespace, variable: e.Name, prefix: prefix, suffix: suffix, transform: transformer}
			expressionAST.Store(p, expressionData{ast, input})
			return p, nil
		case EmailLocalExpr:
			root = e.Inner
		case RegexpReplaceExpr:
			root = e.Inner
		default:
			root = nil
		}
	}
	var transformer transformer
	switch node := ast.(type) {
	case EmailLocalExpr:
		transformer = emailLocalTransformer{}
	case RegexpReplaceExpr:
		transformer = &regexpReplaceTransformer{re: node.re, replacement: node.Replacement}
	}
	p := &Expression{namespace: "", prefix: prefix, suffix: suffix, transform: transformer}
	expressionAST.Store(p, expressionData{ast, input})
	return p, nil
}

func buildVarExpr(parts []string) (interface{}, error) {
	if len(parts) == 1 {
		return parts[0], nil
	}
	if len(parts) != 2 {
		return nil, trace.BadParameter("expected variable in namespace.name form, got %q", strings.Join(parts, "."))
	}
	ns := parts[0]
	if ns != "internal" && ns != "external" && ns != LiteralNamespace {
		return nil, trace.BadParameter("unsupported variable namespace %q", ns)
	}
	if parts[1] == "" {
		return nil, trace.BadParameter("variable name is empty; expected namespace.name")
	}
	return VarExpr{Namespace: ns, Name: parts[1]}, nil
}
func buildVarExprFromProperty(m, k interface{}) (interface{}, error) {
	ns, ok := m.(string)
	if !ok {
		return nil, trace.BadParameter("expected namespace before [\"name\"]")
	}
	name, ok := k.(string)
	if !ok {
		return nil, trace.BadParameter("variable selector must be a string")
	}
	return buildVarExpr([]string{ns, name})
}

